                cur = cur ^ arg
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 1) // 2)
        elif op == '~':
            try:
                cur = ~cur
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 1) // 2)
        elif op == '_':
            try:
                cur = -cur
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 1) // 2)

        i += 2

    return cur

def _format_t(path, root=T):
    if not path:
        return 'T' if root is T else 'S' if root is S else 'A'

    parts = []
    i = 0
    while i < len(path):
        op = path[i]
        arg = path[i + 1]

        if op == '.':
            parts.append(f'.{arg}')
        elif op == '[':
            parts.append(f'[{bbrepr(arg)}]')
        elif op == 'P':
            parts.append(f'.{arg}')
        elif op == '(':
            args, kwargs = arg
            arg_strs = [bbrepr(a) for a in args]
            arg_strs.extend([f'{k}={bbrepr(v)}' for k, v in kwargs.items()])
            parts.append(f'({", ".join(arg_strs)})')
        elif op == 'x':
            parts.append('.__star__()')
        elif op == 'X':
            parts.append('.__starstar__()')
        elif op in ('+', '-', '*', '#', '/', '%', ':', '&', '|', '^'):
            op_map = {'+': '+', '-': '-', '*': '*', '#': '//', '/': '/', '%': '%', ':': '**', '&': '&', '|': '|', '^': '^'}
            parts.append(f' {op_map[op]} {bbrepr(arg)}')
        elif op == '~':
            parts.insert(0, '~')
        elif op == '_':
            parts.insert(0, '-')

        i += 2

    root_str = 'T' if root is T else 'S' if root is S else 'A'
    result = root_str + ''.join(parts)
    return result

def glom(target, spec, **kwargs):
    scope = kwargs.pop('scope', _DEFAULT_SCOPE)
    if not isinstance(scope, ChainMap):
        scope = ChainMap(scope)

    default = kwargs.pop('default', _MISSING)
    skip_exc = kwargs.pop('skip_exc', GlomError)
    glom_debug = kwargs.pop('glom_debug', GLOM_DEBUG)

    if kwargs:
        raise TypeError(f'unexpected keyword arguments: {sorted(kwargs.keys())!r}')

    scope = scope.new_child({
        glom: _glom,
        Path: Path(),
        MODE: AUTO,
        MIN_MODE: None,
    })

    try:
        return scope[glom](target, spec, scope)
    except skip_exc as e:
        if default is not _MISSING:
            return arg_val(target, default, scope)
        if isinstance(e, GlomError):
            e._finalize(scope)
        raise

def __str__(self):
    if getattr(self, '_finalized_str', None):
        return self._finalized_str
    elif getattr(self, '_scope', None) is not None:
        self._target_spec_trace = format_target_spec_trace(self._scope, self.__wrapped)
        parts = ["error raised while processing, details below.",
                 " Target-spec trace (most recent last):",
                 self._target_spec_trace]
        parts.extend(self._tb_lines)
        self._finalized_str = "\n".join(parts)
        return self._finalized_str

    try:
        exc_get_message = self.get_message
    except AttributeError:
        exc_get_message = super().__str__
    return exc_get_message()

def get_message(self):
    path_part = Path(self.path).values()[self.part_idx]
    return ('could not access %r, part %r of %r, got error: %r'
            % (path_part, self.part_idx, self.path, self.exc))

def __repr__(self):
    cn = self.__class__.__name__
    return f'{cn}({self.exc!r}, {self.path!r}, {self.part_idx!r})'

@classmethod
def from_text(cls, text):
    def create():
        segs = text.split('.')
        if PATH_STAR:
            segs = [
                _T_STAR if seg == '*' else
                _T_STARSTAR if seg == '**' else seg
                for seg in segs]
        elif not cls._STAR_WARNED:
            if '*' in segs or '**' in segs:
                warnings.warn(
                    "'*' and '**' have changed behavior in glom version 23.1."
                    " Recommend switch to T['*'] or T['**'].")
                cls._STAR_WARNED = True
        return cls(*segs)

    cache = cls._CACHE[PATH_STAR]
    if text not in cache:
        if len(cache) > cls._MAX_CACHE:
            return create()
        cache[text] = create()
    return cache[text]

def values(self):
    cur_t_path = self.path_t.__ops__
    return cur_t_path[2::2]

def __init__(self, func=None, args=None, kwargs=None):
    if func is None:
        func = T
    if not (callable(func) or isinstance(func, (Spec, TType))):
        raise TypeError('expected func to be a callable or T'
                        ' expression, not: %r' % (func,))
    if args is None:
        args = ()
    if kwargs is None:
        kwargs = {}
    self.func, self.args, self.kwargs = func, args, kwargs

def glomit(self, target, scope):
    r = lambda spec: arg_val(target, spec, scope)
    return r(self.func)(*r(self.args), **r(self.kwargs))

def __call__(self, *args, **kwargs):
    if self is S:
        if args:
            raise TypeError(f'S() takes no positional arguments, got: {args!r}')
        if not kwargs:
            raise TypeError('S() expected at least one kwarg, got none')
    return _t_child(self, '(', (args, kwargs))
